/** SQL text of the fs_line / coa_fs_map seed (pure string building; see scripts/fs-seed-sql.ts). */
import { FS_LINES } from "./fs-lines";
import { coaFsSeed, type MtmAccount } from "./fs-map-seed";

const lit = (v: string | number | boolean | null | undefined): string =>
  v === null || v === undefined ? "null" : typeof v === "number" || typeof v === "boolean" ? String(v) : `'${v.replace(/'/g, "''")}'`;

export function fsLineSeedSql(): string {
  return [
    "-- B8 FS seed 1/2: presentation lines (PRD v2 §5.1 fs_line). Generated by packages/engine/scripts/fs-seed-sql.ts; do not edit by hand.",
    "insert into public.fs_line (code, statement, section, kind, label_id, label_en, bp_row, source_label, sum_codes, level, summary, sort_order) values",
    FS_LINES.map((l, i) => `  (${[lit(l.code), lit(l.statement), lit(l.section), lit(l.kind), lit(l.label_id), lit(l.label_en),
      lit(l.bp_row), lit(l.source_label), l.sum ? `array[${l.sum.map(lit).join(",")}]::text[]` : "null", lit(l.level), lit(!!l.summary), lit(i + 1)].join(", ")})`).join(",\n"),
    "on conflict (code) do nothing;",
    "",
  ].join("\n");
}

export function coaFsSeedSql(accounts: readonly MtmAccount[]): string {
  return [
    "-- B8 FS seed 2/2: account → FS line mapping (PRD v2 §5.1 coa_fs_map, D10). Generated by packages/engine/scripts/fs-seed-sql.ts; do not edit by hand.",
    "insert into public.coa_fs_map (account, account_name, effective_from, effective_to, fs_line_code, sign, accurate_code, confirmed, note, source) values",
    coaFsSeed(accounts).rows.map((r) => `  (${[lit(r.account), lit(r.account_name), lit(r.effective_from), lit(r.effective_to),
      lit(r.fs_line_code), lit(r.sign), lit(r.accurate_code), lit(r.confirmed), lit(r.note), lit(r.source)].join(", ")})`).join(",\n"),
    "on conflict do nothing;",
    "",
  ].join("\n");
}

export function fsSeedSql(accounts: readonly MtmAccount[]): string {
  const lines = FS_LINES.map((l, i) => `  (${[lit(l.code), lit(l.statement), lit(l.section), lit(l.kind), lit(l.label_id), lit(l.label_en),
    lit(l.bp_row), lit(l.source_label), l.sum ? `array[${l.sum.map(lit).join(",")}]::text[]` : "null", lit(l.level), lit(!!l.summary), lit(i + 1)].join(", ")})`);
  const maps = coaFsSeed(accounts).rows.map((r) => `  (${[lit(r.account), lit(r.account_name), lit(r.effective_from), lit(r.effective_to),
    lit(r.fs_line_code), lit(r.sign), lit(r.accurate_code), lit(r.confirmed), lit(r.note), lit(r.source)].join(", ")})`);
  return [
    "-- >>> generated by packages/engine/scripts/fs-seed-sql.ts (do not edit by hand)",
    "insert into public.fs_line (code, statement, section, kind, label_id, label_en, bp_row, source_label, sum_codes, level, summary, sort_order) values",
    lines.join(",\n"),
    "on conflict (code) do nothing;",
    "",
    "insert into public.coa_fs_map (account, account_name, effective_from, effective_to, fs_line_code, sign, accurate_code, confirmed, note, source) values",
    maps.join(",\n"),
    "on conflict do nothing;",
    "-- <<< generated",
    "",
  ].join("\n");
}
